const renderVariableGuide = tab => {
  variableGuideTab = tab; document.querySelectorAll('#variableGuideTabs button').forEach(button => button.classList.toggle('active', button.dataset.guideTab === tab)); const content = $('variableGuideContent'); const fields = state.fields;
  if (tab === 'fields') { const variables = [...fields.map(field => field.name), '表格名', '打印时间']; content.innerHTML = `<p class="guide-intro">将变量复制到 Word 或 Excel 的任意位置，包括正文、表格、页眉和页脚。</p>${variables.length ? `<div class="guide-grid">${variables.map(name => `<article class="guide-card"><span class="guide-field-name">${escapeHtml(name)}</span>${guideCode(`{${name}}`)}</article>`).join('')}</div>` : '<div class="guide-empty">从飞书多维表打开后显示字段变量</div>'}`; }
  if (tab === 'loops') { const loops = loopSourceFields(); content.innerHTML = `<p class="guide-intro">循环字段用于关联记录或列表数据。DOCX 会重复循环区域；XLSX 请把开始、明细变量和结束标记放在同一模板行，生成时自动复制整行并保留公式。</p>${loops.length ? `<div class="guide-grid">${loops.map(field => { const children = field.dependencies?.length ? field.dependencies.slice(0, 6).map(item => item.name) : ['明细字段']; const snippet = `{#${field.name}}\n  {$index+1}\n${children.map(name => `  {${name}}`).join('\n')}\n{/${field.name}}`; return `<article class="guide-card"><h3>${escapeHtml(field.name)}</h3><span class="guide-badge">DOCX / XLSX 支持</span><p>循环根字段；子字段在循环内部直接引用。</p>${guideBlock(snippet)}</article>`; }).join('')}</div>` : '<div class="guide-empty">当前表未识别到关联字段；上传包含 {#循环字段} 的模板后也会自动识别。</div>'}`; }
  if (tab === 'conditions') content.innerHTML = `<p class="guide-intro">DOCX 条件成立时显示内容；支持文本、数字和布尔值比较。匿名结束标签 <code>{/}</code> 可用于比较条件。</p><div class="guide-grid"><article class="guide-card"><h3>有值时显示</h3><p>字段有值或为真时渲染。</p>${guideBlock('{#是否新人}欢迎新人{/是否新人}')}</article><article class="guide-card"><h3>无值时显示</h3><p>兼容原版反向语法。</p>${guideBlock('{#!是否新人}非新人{/是否新人}')}</article><article class="guide-card"><h3>文本比较</h3><p>支持 ==、!=。</p>${guideBlock('{#付款条件=="交付后100%付款"}\n交付后支付100%\n{/}')}</article><article class="guide-card"><h3>数字比较</h3><p>支持 &gt;、&lt;、&gt;=、&lt;=。</p>${guideBlock('{#金额>=1000}大额订单{/}')}</article></div>`;
  if (tab === 'attachments') content.innerHTML = `<p class="guide-intro">普通附件字段可直接输出文件名。原版图片语法依赖可访问的图片地址和 Office 图片模块。</p><div class="guide-grid"><article class="guide-card"><h3>附件文件名</h3><span class="guide-badge">当前支持</span><p>直接显示附件字段返回的文件名。</p>${guideCode('{附件}')}</article><article class="guide-card"><h3>原版图片尺寸语法</h3><span class="guide-badge partial">参考语法</span><p>当前 Office 生成器尚未接入图片二进制下载；在线排版图片组件可使用附件字段。</p>${guideBlock('{#图片} {#$isImage} {%src | size:100:50} {/} {#!$isImage} {$fileName} {/} {/图片}')}</article><article class="guide-card"><h3>最大尺寸</h3><span class="guide-badge partial">参考语法</span><p>Word 中以像素限制最大宽高；Excel 图片按单元格尺寸显示。</p>${guideBlock('{%src | maxSize:500:500}')}</article></div><div class="guide-warning">图片附件语法仅作为原版规则说明展示，程序不会把未支持的图片按钮伪装成可用功能。</div>`;
  if (tab === 'syntax') content.innerHTML = `<p class="guide-intro">以下语法已经接入 DOCX 生成；Excel 公式由 Excel 自身计算。</p><div class="guide-grid"><article class="guide-card"><h3>修改变量分隔符</h3><span class="guide-badge">当前支持</span><p>避免正文中的普通花括号被误识别。</p>${guideBlock('{={{ }}=}\n{这里是普通文字}\n{{项目名称}}')}</article><article class="guide-card"><h3>循环序号</h3><span class="guide-badge">当前支持</span><p>在循环内部从 1 开始编号。</p>${guideCode('{$index+1}')}</article><article class="guide-card"><h3>Excel 当前行公式</h3><span class="guide-badge">Excel 原生</span><p>适用于循环复制后的当前行计算。</p>${guideBlock('=INDIRECT("C"&ROW()) + INDIRECT("A"&ROW())')}</article><article class="guide-card"><h3>字段格式化</h3><span class="guide-badge partial">等待明确规则</span><p>下载指南只引用了另一篇格式化文档，未包含具体语法，因此暂不猜测金额、日期过滤器写法。</p></article></div>`;
  content.querySelectorAll('[data-guide-copy]').forEach(button => button.onclick = () => copyGuideCode(button.dataset.guideCopy));
};
const openVariableGuide = tab => { renderVariableGuide(tab); if (!$('variableGuideDialog').open) $('variableGuideDialog').showModal(); };

$('createTemplate').onclick = $('addTemplate').onclick = () => $('templateFile').click(); $('closeTemplateChoice').onclick = () => $('templateChoiceDialog').close(); $('createLayoutChoice').onclick = () => { $('templateChoiceDialog').close(); openEditor(); }; $('importTemplateChoice').onclick = () => { $('templateChoiceDialog').close(); $('templateFile').click(); }; $('editorExit').onclick = () => { $('editorView').hidden = true; }; $('editorImport').onclick = () => $('templateFile').click(); $('saveOnlineTemplate').onclick = () => { localStorage.setItem(`feiye-editor-${state.context?.tableId || 'local'}`, JSON.stringify({ name: $('editorTitle').textContent.trim(), content: $('editorCanvas').innerHTML, pageSetting: readEditorPageSetting(), savedAt: new Date().toISOString() })); toast('在线模板草稿已保存', 'success'); }; $('editorCanvas').ondragover = event => event.preventDefault(); $('editorCanvas').ondrop = event => { event.preventDefault(); const type = event.dataTransfer.getData('text/layout-component'); if (type) appendComponent(type); }; document.querySelectorAll('.rail-btn').forEach(button => button.onclick = () => { document.querySelectorAll('.rail-btn').forEach(item => item.classList.toggle('active', item === button)); renderEditorPanel(button.dataset.panel); }); $('menuToggle').onclick = () => $('appShell').classList.toggle('menu-collapsed'); $('generateTop').onclick = () => state.selectedTemplate && state.records.length ? $('generate').click() : toast(state.selectedTemplate ? '请先在多维表中选择记录' : '请先导入模板', 'error'); $('batchMode').onclick = openBatchDialog; $('scanTemplate').onclick = async () => { if (!state.selectedTemplate) return toast('请先上传模板', 'error'); $('templateInfo').textContent = `${formatStats(state.selectedTemplate)} · ${variableStats(state.selectedTemplate)}`; await toast('模板变量扫描完成', 'success'); }; $('debugInfo').onclick = () => { const panel = $('dependencyPanel'); panel.hidden = !panel.hidden; $('debugInfo').textContent = panel.hidden ? '显示调试信息' : '隐藏调试信息'; drawDependencies(); }; $('dataSourceVariables').onclick = () => openVariableGuide('fields'); $('variableQuickRef').onclick = () => openVariableGuide('syntax'); $('variableGuide').onclick = () => openVariableGuide('loops'); $('closeVariableGuide').onclick = () => $('variableGuideDialog').close(); document.querySelectorAll('#variableGuideTabs button').forEach(button => button.onclick = () => renderVariableGuide(button.dataset.guideTab)); $('closeGuide').onclick = () => { $('guidePanel').hidden = true; }; $('recordTemplateHelp').onclick = () => showGuide('记录模板', '使用指定记录作为数据源。支持批量模式。可用关联字段数据制作明细表。');
$('closePreview').onclick = () => { $('previewFrame').src = 'about:blank'; $('previewDialog').close(); };
$('closeBatch').onclick = $('cancelBatch').onclick = () => $('batchDialog').close(); $('clearBatch').onclick = () => { batchSelectedIds.clear(); renderBatchTable(); }; $('batchPrev').onclick = async () => { if (batchLoading || batchPage <= 1) return; batchPage--; await loadBatchPage(); }; $('batchNext').onclick = async () => { const pageCount = Math.max(1, Math.ceil(batchRecordIds.length / batchPageSize)); if (batchLoading || batchPage >= pageCount) return; batchPage++; await loadBatchPage(); }; $('batchPageSize').onchange = async event => { batchPageSize = Number(event.target.value); batchPage = 1; await loadBatchPage(); }; $('confirmBatch').onclick = async () => { const ids = batchRecordIds.filter(id => batchSelectedIds.has(id)); if (!ids.length) return toast('请至少选择一条记录', 'error'); const button = $('confirmBatch'); button.disabled = true; button.textContent = '读取中…'; try { const existing = new Map(state.records.map(record => [record.id, record])); const selected = await Promise.all(ids.map(id => existing.get(id) || readBatchRecord(id))); state.records = selected; state.record = selected[0]; state.batchMode = selected.length > 1; $('batchDialog').close(); drawRecord(); updateAction(); await toast(`已选择 ${selected.length} 条记录`, 'success'); } catch (error) { await toast(`读取完整记录失败：${error.message}`, 'error'); } finally { button.disabled = false; button.textContent = '确定'; } };
const showGuide = (title, body) => { $('guideTitle').textContent = title; $('guideBody').textContent = body; $('guidePanel').hidden = false; };
async function uploadTemplate(file) { const headers = { 'content-type': file.type || 'application/octet-stream', 'x-file-name': encodeURIComponent(file.name) }; for (const [key, value] of Object.entries({ 'x-base-id': state.context?.baseId, 'x-table-id': state.context?.tableId, 'x-view-id': state.context?.viewId, 'x-base-name': state.context?.baseName, 'x-table-name': state.context?.tableName })) if (value) headers[key] = encodeURIComponent(value); const response = await fetch(appUrl('/api/templates'), { method: 'POST', headers, body: await file.arrayBuffer() }); const result = await response.json(); if (!response.ok) throw new Error(result.error || '上传失败'); state.templates.unshift(result.template); state.selectedTemplate = result.template; drawTemplates(); await readCurrentRecord(true); await toast('模板已保存并绑定当前数据表', 'success'); await openPreview(result.template.id); }
$('templateFile').onchange = async event => { const file = event.target.files[0]; if (file) try { await uploadTemplate(file); } catch (error) { $('contextMeta').textContent = error.message; await toast(error.message, 'error'); } event.target.value = ''; };
$('editorCanvas').addEventListener('input', event => { if (event.target.isContentEditable && event.target.textContent.endsWith('[')) showFieldSuggest(event.target); });
$('editorCanvas').addEventListener('click', () => { $('fieldSuggest').hidden = true; });
$('closeImageDialog').onclick = $('cancelImage').onclick = () => $('imageDialog').close(); $('closeAttachmentDialog').onclick = $('cancelAttachment').onclick = () => $('attachmentDialog').close();
$('confirmImage').onclick = () => { insertConfiguredComponent('image', $('imageFieldSelect').value); $('imageDialog').close(); }; $('confirmAttachment').onclick = () => { insertConfiguredComponent('attachment', $('attachmentFieldSelect').value); $('attachmentDialog').close(); };
$('refreshRecord').onclick = () => readCurrentRecord(true);
$('outputFormat').onchange = updateAction;
$('generate').onclick = async () => { if (!state.selectedTemplate || !state.records.length) return; const missing = templateFieldDiagnostics().filter(item => !item.matched); if (missing.length) return toast(`模板有 ${missing.length} 个字段未匹配：${missing.map(item => item.name).join('、')}，请先修改模板`, 'error'); const button = $('generate'); button.disabled = true; button.textContent = '生成中…'; try { const records = state.records.map(recordScope); const response = await fetch(appUrl('/api/generate-docx'), { method: 'POST', headers: { 'content-type': 'application/json' }, body: JSON.stringify({ templateId: state.selectedTemplate.id, records, outputFormat: $('outputFormat').value }) }); const result = await response.json(); if (!response.ok || !result.output) throw new Error(result.error || '生成失败'); $('result').hidden = false; $('result').innerHTML = `生成完成。<a href="${appUrl(`/api/outputs/${result.output.id}/download`)}">下载 ${escapeHtml(result.output.name)} ↗</a>`; await toast(`${records.length} 条记录已生成`, 'success'); } catch (error) { await toast(error.message, 'error'); } finally { updateAction(); } };
$('boldText').onclick = () => document.execCommand('bold'); $('italicText').onclick = () => document.execCommand('italic'); $('underlineText').onclick = () => document.execCommand('underline'); $('alignText').onclick = () => document.execCommand('justifyCenter'); $('paragraphStyle').onclick = () => document.execCommand('formatBlock', false, 'p'); $('fontSize').onclick = () => { const sizes = ['9','11','13','16']; const next = sizes[(sizes.indexOf($('fontSize').textContent) + 1) % sizes.length]; $('fontSize').textContent = next; document.execCommand('fontSize', false, String(Math.min(7, sizes.indexOf(next) + 2))); }; $('clearEditor').onclick = () => { $('editorCanvas').innerHTML = '<p class="paper-placeholder">请从左侧拖入组件开始排版</p>'; }; $('undoEditor').onclick = () => document.execCommand('undo'); $('redoEditor').onclick = () => document.execCommand('redo');
const bindSelectionListener = () => { if (selectionBound || !sdk?.bitable?.base) return; selectionBound = true; try { sdk.bitable.base.onSelectionChange(() => { clearTimeout(selectionTimer); selectionTimer = setTimeout(readCurrentRecord, 80); }); } catch {} selectionPoll = setInterval(async () => { try { const current = await sdk.bitable.base.getSelection(); const key = `${current.baseId || ''}/${current.tableId || ''}/${current.viewId || ''}/${selectionRecordIds(current).join(',')}`; if (state.context?.selectionKey && state.context.selectionKey !== key) readCurrentRecord(); } catch {} }, 700); };
readCurrentRecord();
